const KV_PREFIX = 'tdb_';
function kvKey(key) { return KV_PREFIX + key; }
const _enc = typeof TextEncoder !== 'undefined' ? new TextEncoder() : null;
function byteLen(s) { return _enc ? _enc.encode(s).length : s.length; }
const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET,POST,PUT,DELETE,OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type'
};

const HTML_SECURITY_HEADERS = {
  'Content-Type': 'text/html; charset=utf-8',
  'X-Content-Type-Options': 'nosniff',
  'Content-Security-Policy': "default-src 'self'; script-src 'unsafe-inline' 'self'; object-src 'none'; style-src 'unsafe-inline' 'self'; img-src 'self' data: https:; font-src 'self' https:; connect-src 'none'; form-action 'none'; base-uri 'self'; frame-ancestors 'self'",
};

function getMimeType(p) {
  const ext = p.slice(p.lastIndexOf('.')).toLowerCase();
  const types = {
    '.html': 'text/html; charset=utf-8', '.js': 'application/javascript',
    '.css': 'text/css', '.svg': 'image/svg+xml', '.json': 'application/json',
    '.png': 'image/png', '.jpg': 'image/jpeg', '.ico': 'image/x-icon'
  };
  return types[ext] || 'application/octet-stream';
}

async function handleApi(context) {
  const { request } = context;
  const url = new URL(request.url);
  const path = url.pathname;
  // 按官方文档：直接使用全局变量 TEXTDB

  if (request.method === 'OPTIONS') return new Response(null, {status: 204, headers: CORS});

  try {
    if (request.method === 'POST') {
      let key, value;
      const ct = (request.headers.get('content-type') || '').toLowerCase();
      if (path === '/update/' || path === '/update' || path === '/api/update') {
        let params = {};
        if (ct.includes('json')) params = await request.json();
        else {
          const fd = await request.formData();
          params = Object.fromEntries(fd.entries());
        }
        key = (params.key || '').trim();
        value = params.value;
      } else {
        key = path.split('/').pop();
        value = ct.includes('json') ? await request.json().then(v => typeof v === 'string' ? v : JSON.stringify(v)) : await request.text();
      }
      if (!key || !/^[0-9a-zA-Z_]{1,512}$/.test(key)) return new Response(JSON.stringify({status:0, error:'Invalid Key'}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});
      if (!value) {
        const oldVal = await TEXTDB.get(kvKey(key));
        await TEXTDB.delete(kvKey(key));
        try { if (oldVal) { const s = '__stats_size__'; await TEXTDB.put(s, String(Math.max(0, Number(await TEXTDB.get(s) || '0') - byteLen(oldVal)))); } } catch (_) {}
        return new Response(JSON.stringify({status:1, data:{key, action:'deleted'}}), {headers: {...CORS, 'Content-Type':'application/json'}});
      }
      const MAX_VALUE_SIZE = 5 * 1024 * 1024; // 5 MiB（实测 KV 单值上限 5,242,880 B）
      const valueStr = typeof value === 'string' ? value : JSON.stringify(value);
      if (valueStr.length > MAX_VALUE_SIZE) {
        return new Response(JSON.stringify({status:0, error:'Value too large (max 5 MiB)'}), {status:413, headers: {...CORS, 'Content-Type':'application/json'}});
      }
      const oldVal = await TEXTDB.get(kvKey(key));
      await TEXTDB.put(kvKey(key), value);
      // 递增今日写入计数器 + 增量更新总存储量（计数器不加 tdb_ 前缀，天然隔离于用户数据）
      try {
        const today = new Date().toISOString().slice(0, 10);
        const wKey = '__writes__' + today;
        await TEXTDB.put(wKey, String(Number(await TEXTDB.get(wKey) || '0') + 1));
        const newBytes = byteLen(valueStr), oldBytes = oldVal ? byteLen(oldVal) : 0;
        if (newBytes !== oldBytes) { const s = '__stats_size__'; await TEXTDB.put(s, String(Math.max(0, Number(await TEXTDB.get(s) || '0') + newBytes - oldBytes))); }
      } catch (_) { /* 非关键操作 */ }
      return new Response(JSON.stringify({status:1, data:{key, url: url.origin + '/' + key}}), {headers: {...CORS, 'Content-Type':'application/json'}});
    }
    if (request.method === 'GET') {
      const key = path.split('/').pop();
      if (key && /^[0-9a-zA-Z_]{1,512}$/.test(key)) {
        const val = await TEXTDB.get(kvKey(key));
        return new Response(val || '', {headers: {...CORS, 'Content-Type': 'text/plain; charset=utf-8'}});
      }
    }
    if (request.method === 'DELETE') {
      const key = path.split('/').pop();
      const oldVal = await TEXTDB.get(kvKey(key));
      await TEXTDB.delete(kvKey(key));
      try { if (oldVal) { const s = '__stats_size__'; await TEXTDB.put(s, String(Math.max(0, Number(await TEXTDB.get(s) || '0') - byteLen(oldVal)))); } } catch (_) {}
      return new Response(JSON.stringify({status:1, data:{key, action:'deleted'}}), {headers: {...CORS, 'Content-Type':'application/json'}});
    }
    return new Response(JSON.stringify({status:0, error:'Not Found'}), {status:404, headers: {...CORS, 'Content-Type':'application/json'}});
  } catch (e) {
    return new Response(JSON.stringify({status:0, error: e.message}), {status:500, headers: {...CORS, 'Content-Type':'application/json'}});
  }
}

export async function onRequest(context) {
  const { request } = context;
  const url = new URL(request.url);
  const path = url.pathname;

  // OPTIONS 预检（所有路径）
  if (request.method === 'OPTIONS') return new Response(null, {status: 204, headers: CORS});

  // HTML 渲染路由 /p/{key}
  if (request.method === 'GET' && path.startsWith('/p/')) {
    const key = path.slice(3);
    if (key && /^[0-9a-zA-Z_]{1,512}$/.test(key)) {
      const val = await TEXTDB.get(kvKey(key));
      if (val === null) {
        return new Response('Not Found', {status: 404, headers: CORS});
      }
      return new Response(val, {headers: {...HTML_SECURITY_HEADERS, ...CORS}});
    }
    return new Response('Invalid Key', {status: 400, headers: CORS});
  }

  // 文件路由 /file/{ext}/{key} — 根据 ext 自动设置 Content-Type
  if (request.method === 'GET' && path.startsWith('/file/')) {
    const rest = path.slice(6); // 'js/mykey'
    const slashIdx = rest.indexOf('/');
    if (slashIdx > 0) {
      const ext = '.' + rest.slice(0, slashIdx);
      const key = rest.slice(slashIdx + 1);
      if (ext === '.html' || ext === '.svg') {
        return new Response('Use /p/ for HTML/SVG rendering', {status: 400, headers: CORS});
      }
      if (key && /^[0-9a-zA-Z_]{1,512}$/.test(key)) {
        const val = await TEXTDB.get(kvKey(key));
        if (val === null) {
          return new Response('Not Found', {status: 404, headers: CORS});
        }
        const ct = getMimeType(ext);
        const ctFinal = ct.includes('charset') ? ct : ct + '; charset=utf-8';
        const filename = key + ext;
        return new Response(val, {headers: {...CORS, 'Content-Type': ctFinal, 'X-Content-Type-Options': 'nosniff', 'Content-Disposition': 'attachment; filename="' + filename + '"'}});
      }
    }
    return new Response('Invalid Key', {status: 400, headers: CORS});
  }

  // Markdown 渲染路由 /md/{key} — 返回 SPA，前端自行解析渲染
  if (request.method === 'GET' && path.startsWith('/md/')) {
    const key = path.slice(4);
    if (key && /^[0-9a-zA-Z_]{1,512}$/.test(key)) {
      return new Response(STATIC_FILES['/index.html'], {
        headers: {'Content-Type': 'text/html; charset=utf-8', ...CORS}
      });
    }
    return new Response('Invalid Key', {status: 400, headers: CORS});
  }

  // 统计路由（仅 GET）
  if (request.method === 'GET' && (path === '/stats' || path === '/stats/')) {
    let totalKeys = 0, totalSize = 0, writesToday = 0, scannedAll = true, diag = '';
    // 1) list 分页统计 key 数（独立 try，失败不致命）
    try {
      let cursor;
      const MAX_SCAN_KEYS = 5000;
      while (true) {
        const opts = { prefix: KV_PREFIX, limit: 256 };
        if (cursor) opts.cursor = cursor;
        const result = await TEXTDB.list(opts);
        const keys = (result && result.keys) || [];
        totalKeys += keys.length;
        if (totalKeys >= MAX_SCAN_KEYS) { scannedAll = false; break; }
        const done = result.complete || !result.cursor;
        if (done) break;
        cursor = result.cursor;
      }
    } catch (e) { diag += 'list:' + (e && e.message || e) + '; '; }
    // 2) 计数器（独立 try）
    try {
      const today = new Date().toISOString().slice(0, 10);
      writesToday = Number(await TEXTDB.get('__writes__' + today) || '0');
    } catch (e) { diag += 'writes:' + (e && e.message || e) + '; '; }
    try {
      totalSize = Number(await TEXTDB.get('__stats_size__') || '0');
    } catch (e) { diag += 'size:' + (e && e.message || e) + '; '; }
    const payload = {status:1, data:{totalKeys, totalSize, writesToday, scannedAll}};
    if (diag) payload.diag = diag;
    return new Response(JSON.stringify(payload), {headers:{'Content-Type':'application/json', ...CORS}});
  }

  // KV 测试路由
  if (path === '/test-kv' || path === '/test-kv/') {
    try {
      // 按官方文档：直接使用全局变量 TEXTDB
      const val = await TEXTDB.get(kvKey('test_key'));
      let count = Number(val || '0') + 1;
      await TEXTDB.put(kvKey('test_key'), String(count));
      return new Response(JSON.stringify({status:'ok', count:count, message:'KV works!'}), {headers:{'Content-Type':'application/json', ...CORS}});
    } catch (e) {
      return new Response(JSON.stringify({status:'error', error:e.message, stack:e.stack}), {status:500, headers:{'Content-Type':'application/json'}});
    }
  }

  // favicon — 返回 204，避免浏览器自动请求产生 404
  if (request.method === 'GET' && path === '/favicon.ico') {
    return new Response(null, {status: 204, headers: CORS});
  }

  if (path === '/' || path === '/index.html') {
    return new Response(STATIC_FILES['/index.html'], {headers: {'Content-Type': 'text/html; charset=utf-8', ...CORS}});
  }
  if (STATIC_FILES[path]) {
    return new Response(STATIC_FILES[path], {headers: {'Content-Type': getMimeType(path), ...CORS}});
  }
  return handleApi(context);
}